import assert from 'node:assert';
import { test } from 'node:test';
import { createState, frame, collides } from './game/neon.js';

// Mock canvas context
const ctx = {
  fillStyle: '',
  fillRect: () => {},
  beginPath: () => {},
  arc: () => {},
  fill: () => {},
  font: '',
  fillText: () => {},
};

test('D1 - Missing Bounce: ball should bounce off a brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.x = 0; brick.y = 0; brick.w = 100; brick.h = 100;

  state.ball.x = 50;
  state.ball.y = -10;
  state.ball.vy = 100; // Moving down
  state.ball.vx = 0;

  // Move ball into brick
  state.ball.y = 5; // Overlap

  frame(ctx, state);

  assert.strictEqual(state.ball.vy < 0, true, 'Ball should bounce up (vy < 0)');
});

test('D2 - Sticky Collision: ball should be pushed out of the brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.x = 0; brick.y = 0; brick.w = 100; brick.h = 100;

  state.ball.x = 50;
  state.ball.y = 5; // Inside brick
  state.ball.vy = 100;

  // Simulation of a "naive" fix where we just flip vy
  // We'll simulate the naive fix by manually doing what a naive fix would do
  // then check if the ball is still inside.

  // Actually, for this to be a test of the CURRENT code, it will fail because D1 fails.
  // Once D1 is fixed (naive fix: vy = -vy), this test should still fail.

  frame(ctx, state);

  // If we just flipped vy, the ball is still at y=5, which is inside [0, 100]
  const isInside = collides(state.ball, brick);
  assert.strictEqual(isInside, false, 'Ball should be pushed out of the brick');
});

test('D3 - Tunneling: fast ball should not skip the brick', () => {
  const state = createState(10); // High speed
  const brick = state.bricks[0];
  brick.x = 0; brick.y = 0; brick.w = 100; brick.h = 20;

  state.ball.x = 50;
  state.ball.y = -10; // Above brick
  state.ball.vy = 1000; // Very fast

  // One step of 0.05s
  // In a real game, the update loop is: step(state, dt) then frame(ctx, state)
  // Current implementation: step handles walls/paddle, frame handles bricks.

  // This is a bit tricky because the physics is split.
  // Let's assume a large dt.
  const dt = 0.05;
  state.ball.y += state.ball.vy * dt; // 1000 * 0.05 = 50. New y = 40.

  // Now we are at y=40. The brick is at y=0, h=20.
  // The ball is now BELOW the brick.
  // collides() will return false.

  frame(ctx, state);

  // The brick should have been hit and destroyed
  assert.strictEqual(brick.alive, false, 'Brick should be destroyed even if ball tunneled through');
});

